import {dishes,experiences,slots} from './data.js';
import {state,money,esc,icon,toast,save} from './state.js';
let lastFocus;
export function closeModal(){document.querySelector('#overlay').innerHTML='';document.body.classList.remove('locked');lastFocus?.focus();}
export function modal(content,cls=''){lastFocus=document.activeElement;document.querySelector('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="Maison Aurelis"><button class="modal-close icon-button" data-action="close" aria-label="Cerrar">${icon('close')}</button>${content}</section></div>`;document.body.classList.add('locked');document.querySelector('.modal input,.modal select,.modal button')?.focus();}
export function ProductModal(id,editIndex=null){const d=dishes.find(x=>x.id===Number(id)),line=editIndex!==null?state.cart[editIndex]:null;modal(`<div class="product-photo"><img src="${d.image}" alt="${d.name}"></div><form id="product-form" class="product-content" data-id="${id}" data-edit="${editIndex??''}"><div class="eyebrow">MAISON AURELIS / ${d.category}</div><h2>${d.name}</h2><p class="lead">${d.description}</p><span class="product-price">${money(d.price)} ${d.category==='Degustación'?'/ persona':''}</span><h4>Ingredientes principales</h4><p>${d.ingredients}</p><div class="allergy"><strong>Alérgenos</strong><p>${d.allergens}. Preparado en una cocina que manipula otros alérgenos.</p></div><h4>Recomendación del chef</h4><p>${d.chef}</p><label>Preferencias especiales<textarea name="notes" maxlength="350" placeholder="Sin cebolla, término medio, alergias, etc.">${esc(line?.notes||'')}</textarea></label><div class="product-submit"><label>Cantidad<input name="qty" type="number" min="1" max="20" value="${line?.qty||1}" required></label><button class="btn" ${!d.available?'disabled':''}>${line?'Guardar cambios':'Agregar al pedido'} · <span id="product-total">${money(d.price*(line?.qty||1))}</span></button></div></form>`,'product-modal');}
export function Cart(){const sub=state.cart.reduce((a,l)=>a+dishes.find(d=>d.id===l.id).price*l.qty,0);modal(`<div class="eyebrow">MAISON AURELIS</div><h2>Su <em>pedido.</em></h2>${state.cart.length?`<div class="cart-items">${state.cart.map((l,i)=>{const d=dishes.find(x=>x.id===l.id);return `<article class="cart-item"><img src="${d.image}" alt="${d.name}"><div><h3>${d.name}</h3><p>${money(d.price)}</p>${l.notes?`<small>${esc(l.notes)}</small>`:''}<div class="quantity"><button data-action="quantity" data-index="${i}" data-delta="-1" aria-label="Reducir cantidad de ${d.name}">−</button><span>${l.qty}</span><button data-action="quantity" data-index="${i}" data-delta="1" aria-label="Aumentar cantidad de ${d.name}">+</button><button data-action="edit-cart" data-index="${i}">Editar</button><button data-action="remove" data-index="${i}" aria-label="Eliminar ${d.name}">Eliminar</button></div></div><strong>${money(d.price*l.qty)}</strong></article>`}).join('')}</div><div class="totals"><div><span>Subtotal</span><span>${money(sub)}</span></div><div><span>Servicio · 10%</span><span>${money(sub*.1)}</span></div><div class="total"><span>Total</span><strong>${money(sub*1.1)}</strong></div></div><button class="btn full" data-action="checkout">Continuar pedido ${icon('arrow')}</button><p class="fine-print">Experiencia de demostración. No se realizan cobros reales.</p>`:`<div class="empty">${icon('bag')}<h3>Un gran momento empieza con un plato.</h3><p>Explore nuestra carta y añada sus favoritos.</p><button class="btn" data-action="browse">Explorar la carta</button></div>`}`,'cart-modal');}
let checkout={step:1,delivery:'Room Service',timing:'now',payment:'Cargo a habitación',info:{}};
export function Checkout(reset=false){if(reset){const scheduled=state.cart.find(l=>l.schedule);checkout={step:1,delivery:'Room Service',timing:scheduled?'schedule':'now',payment:'Cargo a habitación',info:scheduled?{schedule:scheduled.schedule}:{}};}const c=checkout,sub=state.cart.reduce((a,l)=>a+dishes.find(d=>d.id===l.id).price*l.qty,0);modal(`<div class="eyebrow">UNA EXPERIENCIA A SU MEDIDA</div><h2>Finalizar <em>pedido.</em></h2><ol class="steps">${['Pedido','Información','Pago','Confirmación'].map((s,i)=>`<li class="${c.step===i+1?'current':c.step>i+1?'done':''}">${i+1}<span>${s}</span></li>`).join('')}</ol>${c.step===1?`<h3>¿Cómo desea recibir su pedido?</h3><div class="choice-grid">${['Room Service','Recoger en restaurante','Mesa del restaurante'].map(s=>`<button data-action="delivery" data-value="${s}" class="choice ${c.delivery===s?'selected':''}">${s}</button>`).join('')}</div><div class="totals"><div><span>${state.cart.reduce((a,l)=>a+l.qty,0)} productos · Servicio incluido</span><strong>${money(sub*1.1)}</strong></div></div><button class="btn full" data-action="checkout-next">Continuar a información</button>`:c.step===2?`<form id="checkout-info"><h3>${c.delivery}</h3><div class="form-grid">${field('Nombre','first','text',c.info.first)}${field('Apellido','last','text',c.info.last)}${field('Teléfono','phone','tel',c.info.phone)}${c.delivery==='Room Service'?field('Número de habitación','room','text',c.info.room||sessionStorage.getItem('aur-room')):c.delivery==='Mesa del restaurante'?field('Número de mesa','table','number',c.info.table):field('Email','email','email',c.info.email)}</div><label>Horario de entrega<select id="delivery-timing" name="timing"><option value="now" ${c.timing==='now'?'selected':''}>Entregar ahora</option><option value="schedule" ${c.timing==='schedule'?'selected':''}>Programar pedido</option></select></label><div id="schedule-fields" ${c.timing==='now'?'hidden':''}>${field('Fecha y hora','schedule','datetime-local',c.info.schedule,c.timing!=='now')}</div><label>Instrucciones<textarea name="instructions" maxlength="500">${esc(c.info.instructions||'')}</textarea></label><div class="button-row"><button type="button" class="btn outline" data-action="checkout-back">Volver</button><button class="btn">Continuar al pago</button></div></form>`:`<h3>Método de pago</h3><p class="demo-banner">Pago simulado. No introduzca datos bancarios reales.</p><div class="choice-grid payment">${['Tarjeta','Apple Pay','Google Pay',...(c.delivery==='Room Service'?['Cargo a habitación']:[])].map(s=>`<button class="choice ${c.payment===s?'selected':''}" data-action="payment" data-value="${s}">${s}</button>`).join('')}</div><div class="demo-card">${c.payment==='Tarjeta'?'<span>TARJETA DEMO</span><strong>4242 · 4242 · 4242 · 4242</strong><span>AURELIS GUEST · 12/30</span>':`<strong>${c.payment}</strong><span>Autorización simulada · Sin cargos</span>`}</div><div class="order-summary"><p>${esc(c.info.first)} ${esc(c.info.last)} · ${c.delivery}</p><p>${c.delivery==='Room Service'?'Habitación '+esc(c.info.room):c.delivery==='Mesa del restaurante'?'Mesa '+esc(c.info.table):'Recogida en Maison Aurelis'}</p><p>${c.timing==='now'?'Entrega estimada: 35–45 minutos':esc(c.info.schedule?.replace('T',' · '))}</p></div><div class="totals"><div class="total"><span>Total · Servicio incluido</span><strong>${money(sub*1.1)}</strong></div></div><div class="button-row"><button class="btn outline" data-action="checkout-back">Volver</button><button class="btn" data-action="confirm-order">Confirmar pedido simulado</button></div>`}`,'form-modal');}
export function checkoutAction(action,value){if(action==='delivery'){checkout.delivery=value;checkout.payment=value==='Room Service'?'Cargo a habitación':'Tarjeta';}if(action==='payment')checkout.payment=value;if(action==='checkout-next')checkout.step++;if(action==='checkout-back')checkout.step--;Checkout();}
export function checkoutInfo(form){checkout.info=Object.fromEntries(new FormData(form));checkout.timing=checkout.info.timing;if(checkout.timing==='schedule'&&new Date(checkout.info.schedule)<new Date()){toast('Seleccione un horario futuro.');return;}checkout.step=3;Checkout();}
export function confirmOrder(){const total=state.cart.reduce((a,l)=>a+dishes.find(d=>d.id===l.id).price*l.qty,0)*1.1;const id='AUR-'+String(Date.now()).slice(-6);state.orders.unshift({id,items:structuredClone(state.cart),total,delivery:checkout.delivery,created:Date.now(),timing:checkout.timing,schedule:checkout.info.schedule});state.cart=[];save();modal(`<div class="success-mark">${icon('check')}</div><div class="eyebrow">GRACIAS POR ELEGIR AURELIS</div><h2>Su pedido<br>ha sido <em>recibido.</em></h2><p>Estamos preparando una experiencia especial para usted.</p><div class="confirmation-code">${id}</div><p>${checkout.timing==='now'?'Tiempo estimado: 35–45 minutos':'Entrega programada: '+esc(checkout.info.schedule.replace('T',' · '))}</p><p>Total simulado: ${money(total)}</p><button class="btn" data-action="order-status" data-id="${id}">Ver estado del pedido</button><p class="fine-print">Confirmación de demostración. No se enviará ningún pedido ni se realizará un cobro.</p>`,'success-modal');}
export function OrderStatus(id){const o=state.orders.find(o=>o.id===id);if(!o)return;const phase=o.timing==='schedule'?0:Math.min(3,Math.floor((Date.now()-o.created)/60000));modal(`<div class="eyebrow">SEGUIMIENTO SIMULADO</div><h2>Su experiencia<br><em>en camino.</em></h2><p>${o.id} · ${o.delivery}</p><ol class="status-list">${['Pedido recibido','En preparación','Últimos detalles','Listo para servir'].map((s,i)=>`<li class="${i<=phase?'done':''}">${icon('check')}<span>${s}</span></li>`).join('')}</ol><p>${o.timing==='schedule'?'Programado: '+esc(o.schedule?.replace('T',' · ')):'Tiempo estimado: 35–45 minutos'}</p><button class="btn outline" data-action="order-status" data-id="${id}">Actualizar estado</button>`,'form-modal');}
export function field(label,name,type='text',value='',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value||'')}" ${required?'required':''} ${type==='date'?`min="${today()}"`:''} ${type==='number'?'min="1" max="200"':''} ${type==='tel'?'pattern="[+0-9 ()-]{7,20}"':''} maxlength="120"></label>`;}
export function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
let booking={};
export function ReservationsForm(step=1){modal(`<div class="eyebrow">MAISON AURELIS · RESERVAS</div><h2>Una mesa.<br>Mil <em>recuerdos.</em></h2><p>Disponibilidad de demostración · Servicio de cena</p>${step===1?`<form id="reserve-availability"><div class="form-grid">${field('Fecha','date','date',booking.date)}<label>Personas<select name="guests">${[1,2,3,4,5,6,7,8].map(n=>`<option ${Number(booking.guests||2)===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Hora preferida<select name="preferred">${slots.map(s=>`<option>${s}</option>`).join('')}</select></label></div><button class="btn full">Consultar horarios disponibles</button><p class="fine-print">Para más de 8 invitados, contacte con nuestro concierge.</p></form>`:step===2?`<p>${esc(booking.date)} · ${booking.guests} invitados</p><h3>Seleccione un horario disponible</h3><div class="slots">${slots.map(s=>{const past=booking.date===today()&&s<=new Date().toTimeString().slice(0,5);const taken=state.reservations.some(r=>r.kind==='Mesa'&&r.date===booking.date&&r.time===s);return `<button class="choice ${s===booking.preferred?'preferred':''}" data-action="reserve-slot" data-value="${s}" ${past||taken||s==='20:00'?'disabled':''}>${s}<small>${past||taken||s==='20:00'?'Completo':'Disponible'}</small></button>`}).join('')}</div><button class="text-link" data-action="reserve">Cambiar fecha</button>`:`<p>${esc(booking.date)} · ${booking.time} · ${booking.guests} invitados</p><form id="reserve-details"><div class="form-grid">${field('Nombre','first')}${field('Apellido','last')}${field('Email','email','email')}${field('Teléfono','phone','tel')}<label>Ocasión especial<select name="occasion">${['Cena','Aniversario','Cumpleaños','Negocios','Propuesta','Celebración privada'].map(s=>`<option>${s}</option>`).join('')}</select></label>${field('Preferencias','preferences','text','',false)}</div><label>Alergias<textarea name="allergies" placeholder="Indique cualquier restricción alimentaria" maxlength="500"></textarea></label><label>Comentarios<textarea name="comments" maxlength="500"></textarea></label><p class="fine-print">Reserva simulada. Los datos permanecen únicamente en este navegador.</p><button class="btn full">Confirmar reserva</button></form>`}`,'form-modal');}
export function reserveAvailability(form){booking=Object.fromEntries(new FormData(form));if(new Date(booking.date+'T12:00:00').getDay()===1){toast('Maison Aurelis descansa los lunes. Elija otro día.');return;}if(booking.date<today()){toast('Seleccione una fecha futura.');return;}ReservationsForm(2);}
export function reserveSlot(time){booking.time=time;ReservationsForm(3);}
export function reserveConfirm(form){const values=Object.fromEntries(new FormData(form));const id='RES-'+String(Date.now()).slice(-6);state.reservations.unshift({id,kind:'Mesa',...booking,first:values.first,occasion:values.occasion});save();Success('Su mesa está reservada.',`${values.first}, le esperamos el ${booking.date} a las ${booking.time}. ${booking.guests} invitados.`,id);}
export function Success(title,message,id,concierge=false){modal(`<div class="success-mark">${icon('check')}</div><div class="eyebrow">AURELIS GRAND HOTEL</div><h2>${title}</h2><p>${esc(message)}</p><div class="confirmation-code">${id}</div>${concierge?'<p>Solicitud recibida. Esta experiencia requiere confirmación del concierge.</p>':''}<p class="fine-print">Demostración ficticia. No se envían correos ni solicitudes reales.</p><button class="btn" data-action="close">Continuar explorando</button>`,'success-modal');}
export function Experience(id){const e=experiences.find(x=>x.id===id);modal(`<img class="experience-modal-photo" src="/assets/${e.image}.webp" alt="${e.name}"><div class="padded"><div class="eyebrow">EXPERIENCIAS AURELIS</div><h2>${e.name}</h2><p>${e.description}</p><p class="product-price">Desde ${money(e.price)} ${e.unit}</p><p>Incluye atención personalizada, selección gastronómica y coordinación previa. Hasta ${e.max} invitados. Disponibilidad sujeta a confirmación del concierge.</p><form id="experience-form" data-experience="${id}"><div class="form-grid"><label>Experiencia<input value="${e.name}" readonly></label>${field('Fecha','date','date')}<label>Invitados<input type="number" name="guests" min="${e.id==='romantic'?2:1}" max="${e.max}" value="2" required></label>${field('Nombre','name')}${field('Teléfono','phone','tel')}${field('Email','email','email')}</div><label>Comentarios<textarea name="comments" maxlength="500"></textarea></label><button class="btn full">Solicitar experiencia</button><p class="fine-print">Solicitud simulada · Requiere confirmación del concierge</p></form></div>`,'experience-modal');}
export function EventForm(){modal(`<div class="eyebrow">PRIVATE EVENTS</div><h2>Un momento<br><em>solo suyo.</em></h2><form id="event-form"><div class="form-grid"><label>Tipo de evento<select name="event">${['Cena empresarial','Boda','Aniversario','Reunión privada','Celebración','Evento corporativo'].map(x=>`<option>${x}</option>`).join('')}</select></label>${field('Invitados','guests','number')}${field('Fecha','date','date')}${field('Nombre','name')}${field('Empresa (opcional)','company','text','',false)}${field('Teléfono','phone','tel')}${field('Email','email','email')}</div><label>Mensaje<textarea name="message" maxlength="1000" required></textarea></label><button class="btn full">Solicitar propuesta</button><p class="fine-print">Formulario de demostración. No envía solicitudes reales.</p></form>`,'form-modal');}
export function BreakfastForm(){modal(`<div class="eyebrow">MAÑANAS A SU RITMO</div><h2>Un despertar<br><em>extraordinario.</em></h2><form id="breakfast-form"><label>Desayuno<select name="breakfast">${dishes.filter(d=>d.category==='Desayuno').map(d=>`<option value="${d.id}">${d.name} · ${money(d.price)} / persona</option>`).join('')}</select></label><div class="form-grid">${field('Fecha','date','date')}<label>Hora<select name="time">${['06:30','07:00','07:30','08:00','08:30','09:00','09:30','10:00','10:30'].map(x=>`<option>${x}</option>`).join('')}</select></label>${field('Habitación','room','text',sessionStorage.getItem('aur-room'))}<label>Personas<input name="guests" type="number" min="1" max="8" value="2" required></label></div><p class="fine-print">Se añadirá al pedido con sus preferencias de horario. Complete el checkout para confirmar.</p><button class="btn full">Añadir desayuno programado</button></form>`,'form-modal');}
export function Concierge(){modal(`<div class="eyebrow">A SU DISPOSICIÓN</div><h2>Concierge <em>Aurelis</em></h2><p>Estamos disponibles para asistirle con reservas, experiencias privadas y solicitudes especiales.</p><div class="concierge-options"><button data-action="reserve">Reservar restaurante ${icon('arrow')}</button><button data-action="special-request">Pedido especial ${icon('arrow')}</button><button data-action="event">Evento privado ${icon('arrow')}</button><button data-action="concierge-chat">Hablar con concierge ${icon('arrow')}</button></div><p class="fine-print">+51 900 000 000 — Demo<br>Atención simulada. No se abre un chat de WhatsApp real.</p>`,'form-modal');}
export function Profile(){modal(`<div class="eyebrow">BIENVENIDO A AURELIS</div><h2>Su espacio <em>privado.</em></h2><p>Perfil de invitado · Guardado solo en este navegador</p><button class="text-link" data-action="show-favorites">Mis favoritos (${state.favorites.length}) ${icon('heart')}</button><h3>Sus pedidos</h3>${state.orders.length?state.orders.map(o=>`<button class="record" data-action="order-status" data-id="${o.id}"><span>${o.id}<small>${new Date(o.created).toLocaleDateString()} · ${o.delivery}</small></span><strong>${money(o.total)} →</strong></button>`).join(''):'<p>Aún no ha realizado un pedido.</p>'}<h3>Sus reservas y solicitudes</h3>${state.reservations.length?state.reservations.map(r=>`<div class="record"><span>${esc(r.kind)}<small>${esc(r.date)} ${esc(r.time||'')} · ${esc(r.guests||'')} invitados</small></span><span>${r.id}</span></div>`).join(''):'<p>Sus próximas experiencias aparecerán aquí.</p>'}`,'form-modal');}

